        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                squares.add((r + 1, c + 1, color))

    out = [row[:] for row in grid]
    horizontal = {}
    vertical = {}
    for r, c, color in squares:
        horizontal[r] = color
        vertical[c] = color

