        for c in range(w):
            out[r][c] = color
    for c, color in vertical.items():
        for r in range(h):
            out[r][c] = color

    # Where a horizontal ray and a differently colored vertical ray cross,
    # leave the crossing blank.
    for r, hcolor in horizontal.items():
        for c, vcolor in vertical.items():
            if hcolor != vcolor:
                out[r][c] = 0
    return out
